import { inject, Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

@Injectable({
  providedIn: 'root',
})
export class SwitchLanguageService {
  currentLanguage = 'en';

  private readonly translateService: TranslateService = inject(TranslateService);

  constructor() {
    const stored = typeof window !== 'undefined' ? window.localStorage.getItem('keira.lang') : null;
    this.currentLanguage = stored ?? this.translateService.currentLang ?? this.translateService.getDefaultLang() ?? 'en';
  }

  setLanguage(event: Event): void {
    const lang = (event.target as HTMLSelectElement).value;
    this.currentLanguage = lang;

    if (typeof window !== 'undefined') {
      window.localStorage.setItem('keira.lang', lang);
    }

    this.translateService.setDefaultLang(lang);
    this.translateService.use(lang).subscribe();
  }
}
