.wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  background-size: cover;
  height: 100vh;
}
.wrapper .content {
  position: relative;
  width: 500px;
  min-height: 55px;
  background-color: rgba(0, 0, 0, 0.5);
  border-radius: 30px;
  padding: 30px;
  color: white;
}
.wrapper .content .title {
  text-align: center;
}
.wrapper .content .form-wrapper {
  max-width: 360px;
  margin: 20px auto auto;
}
.wrapper .content .form-wrapper .recent-container {
  margin-bottom: 6px;
  padding-right: 4px;
}
.wrapper .content .form-wrapper .recent-container .form-check-input {
  width: 16px;
  height: 16px;
}
.wrapper .content .form-wrapper .recent-container .form-check-label {
  margin-top: 2px;
  font-weight: bold;
}
.wrapper .content .form-wrapper .recent-container .btn-group {
  float: right;
}
.wrapper .content .form-wrapper .recent-container .btn-group .dropdown-menu {
  background-color: #000;
}
.wrapper .content .form-wrapper .recent-container .btn-group .dropdown-menu a {
  font-weight: bold;
  color: #fff;
}
.wrapper .content .form-wrapper .recent-container .btn-group .dropdown-menu a:hover,
.wrapper .content .form-wrapper .recent-container .btn-group .dropdown-menu a:focus,
.wrapper .content .form-wrapper .recent-container .btn-group .dropdown-menu a:active {
