}
.wrapper .content .form-wrapper .form-group {
  display: flex;
}
.wrapper .content .form-wrapper .form-group .input-group-prepend span {
  width: 130px;
  font-weight: bold;
  color: #fff;
  border: 0 !important;
}
.wrapper .content .form-wrapper .form-group .input-group-prepend span i {
  margin-right: 10px;
  margin-bottom: 2px;
}
.wrapper .content .form-wrapper .form-group .form-control {
  width: auto;
  border-top-left-radius: 0;
  border-bottom-left-radius: 0;
}
.wrapper .content .form-wrapper .connect-button {
  font-weight: bold;
  width: 70%;
  margin: auto;
  display: block;
}
.wrapper .content .form-wrapper .btn {
  font-weight: bold;
}
.wrapper .content .form-wrapper .btn:focus {
  box-shadow: none;
}
.wrapper .content .end-text {
  position: absolute;
  bottom: 10px;
  left: 50%;
  transform: translateX(-50%);
}
.wrapper .content .end-text a,
.wrapper .content .end-text a:hover {
  font-weight: bold;
  text-decoration: none;
