import { Pipe, PipeTransform, inject } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

@Pipe({
  name: 'translateOrFallback',
  standalone: true,
})
export class TranslateOrFallbackPipe implements PipeTransform {
  private readonly translate = inject(TranslateService);

  transform(key: string | null | undefined, fallback: string): string {
    if (!key) {
      return fallback;
    }

    const translated = this.translate.instant(key);
    if (translated && translated !== key) {
      return translated;
    }

    return this.humanizeFallbackForChinese(fallback);
  }

  private humanizeFallbackForChinese(fallback: string): string {
    const lang = (this.translate.currentLang || this.translate.defaultLang || '').toLowerCase();
    if (!lang.startsWith('zh')) {
      return fallback;
    }

    const value = (fallback || '').trim();
    if (!value) {
      return fallback;
    }

    // Only try to humanize token-like strings to avoid mangling normal English sentences.
    // Also accept "TOKEN something" patterns where the suffix is usually a comment like "unused".
    const leadingTokenMatch = /^([A-Z0-9_]+)(?:\s+(.*))?$/.exec(value);
    const leadingToken = leadingTokenMatch?.[1] ?? '';
    const trailingComment = (leadingTokenMatch?.[2] ?? '').trim();

    const looksLikeToken = /^[A-Z0-9_]+$/.test(value);
    const looksLikeLowerWord = /^[a-z_]+$/.test(value);
    if (!looksLikeToken && !looksLikeLowerWord && !leadingToken) {
      return fallback;
    }

    const dict: Record<string, string> = {
      NONE: '无',
      UNUSED: '未使用',
      ONESHOT: '单次',
      STATE: '状态',
      STAND: '站立',
      TALK: '说话',
      BOW: '鞠躬',
      WAVE: '挥手',
      CHEER: '欢呼',
      EXCLAMATION: '惊叹',
      QUESTION: '疑问',
      EAT: '进食',
      DANCE: '跳舞',
      LAUGH: '大笑',
      SLEEP: '睡觉',
      SIT: '坐下',
      RUDE: '粗鲁',
      ROAR: '咆哮',
      KNEEL: '跪下',
      KISS: '亲吻',
      CRY: '哭泣',
      CHICKEN: '学小鸡',
      BEG: '乞求',
      APPLAUD: '鼓掌',
      SHOUT: '大喊',
      FLEX: '展示肌肉',
      SHY: '害羞',
      POINT: '指向',
      READY: '准备',
      UNARMED: '徒手',
      WORK: '工作',
      SHEATHED: '收鞘',
      SHEATHE: '收鞘',
      SHEATH: '收鞘',
      WOUND: '受伤',
      CRITICAL: '致命',
      ATTACK: '攻击',
      PARRY: '招架',
      SHIELD: '盾牌',
      SPELL: '法术',
      PRECAST: '预施放',
      CAST: '施放',
      BATTLE: '战斗',
      KICK: '踢',
      THROWN: '投掷',
      STUN: '昏迷',
      DEAD: '死亡',
      SALUTE: '敬礼',
      USE: '使用',
      YES: '是',
      NO: '否',
      TRAIN: '训练',
      LAND: '落地',
      EASE: '休息',
      SUBMERGED: '潜入',
      SUBMERGE: '潜入',
      RIFLE: '火枪',
      MINING: '采矿',
      CHOPWOOD: '砍柴',
      LOOT: '拾取',
      DROWN: '溺水',
      DROWNED: '溺水',
      HOLD: '持握',
      MOUNT: '骑乘',
      FALL: '坠落',
      COWER: '畏缩',
      STEALTH: '潜行',
      DODGE: '闪避',
      FLY: '飞行',

      // Spell-style tokens
      SCHOOL: '系',
      DAMAGE: '伤害',
      APPLY: '施加',
      AURA: '光环',
      HEAL: '治疗',
      SUMMON: '召唤',
      TELEPORT: '传送',
      PORTAL: '传送门',
      WEAPON: '武器',
      HEALTH: '生命值',
      POWER: '能量',
      MOD: '调整',
      PERIODIC: '周期',
      INCREASE: '提高',
      DECREASE: '降低',
      SPEED: '速度',
      ATTACKSPEED: '攻击速度',
      THREAT: '威胁值',
      TAUNT: '嘲讽',
      CONFUSE: '困惑',
      CHARM: '魅惑',
      FEAR: '恐惧',
      ROOT: '定身',
      SILENCE: '沉默',
      INVISIBILITY: '隐形',
      DETECT: '侦测',
      RESISTANCE: '抗性',
      STAT: '属性',
      SKILL: '技能',
      SHAPESHIFT: '变形',
      IMMUNITY: '免疫',
      DUMMY: '占位',
      INSTAKILL: '秒杀',
      CUSTOM: '自定义',
      RESURRECT: '复活',
      DISPEL: '驱散',
      TRIGGER: '触发',
      EFFECT: '效果',
    };

    if (looksLikeLowerWord) {
      const lowerDict: Record<string, string> = {
        charmed: '魅惑',
        disoriented: '迷惑',
        disarmed: '缴械',
        distracted: '分心',
        fleeing: '恐惧（逃跑）',
        gripped: '拉拽',
        rooted: '定身',
        slowed: '减速',
        silenced: '沉默',
        asleep: '睡眠',
        snared: '缠绕',
        stunned: '昏迷',
        frozen: '冻结',
        incapacitated: '瘫痪',
        bleeding: '流血',
        healing: '治疗',
        polymorphed: '变形',
        banished: '放逐',
        shielded: '护盾',
        shackled: '束缚',
        mounted: '骑乘',
        infected: '感染',
        turned: '恐惧（转向）',
        horrified: '惊骇',
        invulnerable: '无敌',
        interrupted: '打断',
        dazed: '眩晕（迟缓）',
        discovery: '发现',
        sapped: '闷棍',
        enraged: '狂暴',
      };
      return lowerDict[value] ?? fallback;
    }

    // Prefer to humanize the leading token even if there is a trailing comment.
    const tokenToHumanize = looksLikeToken ? value : leadingToken;
    const parts = tokenToHumanize.split('_');
    if (parts.length === 1) {
      const one = dict[tokenToHumanize] ?? fallback;
      if (!trailingComment) {
        return one;
      }
      if (/^unused$/i.test(trailingComment)) {
        return `${one}（未使用）`;
      }
      return one;
    }

    // Special-case common long prefixes to avoid awkward outputs like "法术光环..."
    if (tokenToHumanize.startsWith('SPELL_AURA_')) {
      const trimmed = tokenToHumanize.slice('SPELL_AURA_'.length);
      return `光环：${this.humanizeFallbackForChinese(trimmed)}`;
    }

    const [first, ...rest] = parts;
    const firstZh = dict[first] ?? first;
    const restZh = rest.map((p) => dict[p] ?? p).join('');

    if (first === 'NO') {
      const combinedNo = `不${restZh}`;
      return combinedNo === tokenToHumanize ? fallback : combinedNo;
    }

    // Prefer a category-like prefix for common patterns.
    if (first === 'ONESHOT' || first === 'STATE') {
      return restZh ? `${firstZh}：${restZh}` : firstZh;
    }

    const combined = `${firstZh}${restZh}`;
    const result = combined === tokenToHumanize ? fallback : combined;
    if (!trailingComment) {
      return result;
    }
    if (/^unused$/i.test(trailingComment)) {
      return `${result}（未使用）`;
    }
    return result;
  }
}
