import { inject, Pipe, PipeTransform } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

@Pipe({
  name: 'fieldLabel',
  standalone: true,
  pure: false,
})
export class FieldLabelPipe implements PipeTransform {
  private readonly translate = inject(TranslateService);
  private lastKey?: string;
  private lastLang?: string;
  private lastValue: string = '';

  transform(fieldName: string | null | undefined, prefix = 'FIELDS'): string {
    if (!fieldName) {
      return '';
    }

    const key = `${prefix}.${fieldName}`;
    const lang = this.translate.currentLang || this.translate.defaultLang || '';

    if (key === this.lastKey && lang === this.lastLang) {
      return this.lastValue || fieldName;
    }

    const translated = this.translate.instant(key);

    let value = translated && translated !== key ? translated : '';

    if (!value) {
      const indexed = /^(?<base>.+?)(?:_(?<n1>\d+)|(?<n2>\d+))$/.exec(fieldName);
      const base = indexed?.groups?.['base'];
      const index = indexed?.groups?.['n1'] || indexed?.groups?.['n2'];

      if (base && index) {
        const baseKey = `${prefix}.${base}`;
        const baseTranslated = this.translate.instant(baseKey);

        if (baseTranslated && baseTranslated !== baseKey) {
          value = `${baseTranslated}${index}`;
        }
      }
    }

    this.lastKey = key;
    this.lastLang = lang;
    this.lastValue = value || fieldName;

    return this.lastValue || fieldName;
  }
}
