/* libs/main/main-window/src/sidebar/sidebar.component.scss */
@keyframes swing {
  0% {
    transform: rotate(0deg);
  }
  10% {
    transform: rotate(10deg);
  }
  30% {
    transform: rotate(0deg);
  }
  40% {
    transform: rotate(-10deg);
  }
  50% {
    transform: rotate(0deg);
  }
  60% {
    transform: rotate(5deg);
  }
  70% {
    transform: rotate(0deg);
  }
  80% {
    transform: rotate(-5deg);
  }
  100% {
    transform: rotate(0deg);
  }
}
.sidebar {
  width: 240px;
  height: 100%;
  max-height: 100%;
  position: fixed;
  top: 0;
  left: 0;
  z-index: 999;
  transition: left 0.3s ease;
}
.sidebar hr {
  color: #fff;
  border-top: 1px solid rgba(255, 255, 255, 0.6);
  margin: 4px 10px;
}
.sidebar a {
  text-decoration: none;
  transition: color 0.3s ease;
}
.sidebar .sidebar-content {
  max-height: calc(100% - 30px);
  height: calc(100% - 30px);
  overflow-y: auto;
  position: relative;
}
.sidebar .sidebar-content .sidebar-header {
  font-size: 0.8rem;
  text-align: center;
  padding: 10px 20px;
  display: flex;
  align-items: center;
}
.sidebar .sidebar-content .sidebar-header > a {
  text-transform: uppercase;
  font-weight: bold;
  flex-grow: 1;
  text-decoration: none;
}
.sidebar .sidebar-content .sidebar-profile {
  padding: 14px 18px;
  overflow: hidden;
}
.sidebar .sidebar-content .sidebar-profile .user-pic {
  float: left;
  width: 60px;
  padding: 2px;
  border-radius: 12px;
  margin-right: 15px;
  overflow: hidden;
}
.sidebar .sidebar-content .sidebar-profile .user-pic img {
  object-fit: cover;
  height: 100%;
  width: 100%;
}
.sidebar .sidebar-content .sidebar-profile .user-info {
  float: left;
}
.sidebar .sidebar-content .sidebar-profile .user-info > span {
  display: block;
}
.sidebar .sidebar-content .sidebar-profile .user-info .db-user,
.sidebar .sidebar-content .sidebar-profile .user-info .db-name {
  font-size: 12px;
  color: #bdbdbd;
}
.sidebar .sidebar-content .sidebar-profile .user-info .db-host {
  font-size: 0.8rem;
}
.sidebar .sidebar-content .sidebar-profile .user-info .db-host .port {
  color: lightgray;
}
.sidebar .sidebar-content .sidebar-profile .user-info .user-status {
  font-size: 11px;
  margin-top: 4px;
}
.sidebar .sidebar-content .sidebar-profile .user-info .user-status i {
  font-size: 8px;
  margin-right: 4px;
}
.sidebar .sidebar-content .sidebar-profile .user-info .user-status i.connection-status {
  color: red;
}
.sidebar .sidebar-content .sidebar-profile .user-info .user-status i.connection-status.connected,
.sidebar .sidebar-content .sidebar-profile .user-info .user-status i.connection-status.authenticated {
  color: #5cb85c;
}
.sidebar .sidebar-content .sidebar-menu {
  padding-top: 4px;
  padding-bottom: 10px;
}
.sidebar .sidebar-content .sidebar-menu .header-menu span {
  font-weight: bold;
  font-size: 14px;
  padding: 15px 20px 5px 20px;
  display: inline-block;
}
.sidebar .sidebar-content .sidebar-menu ul {
  list-style-type: none;
  padding: 0;
  margin: 0;
}
.sidebar .sidebar-content .sidebar-menu ul li a {
  display: inline-block;
  width: 100%;
  text-decoration: none;
  position: relative;
  padding: 8px 30px 8px 10px;
  cursor: pointer;
}
.sidebar .sidebar-content .sidebar-menu ul li a i {
  margin-right: 10px;
  font-size: 0.9rem;
  width: 30px;
  height: 30px;
  line-height: 30px;
  text-align: center;
  border-radius: 4px;
}
.sidebar .sidebar-content .sidebar-menu ul li a:hover > i::before {
  display: inline-block;
  animation: swing ease-in-out 0.5s 1 alternate;
}
.sidebar .sidebar-content .sidebar-menu ul li a span.label,
.sidebar .sidebar-content .sidebar-menu ul li a span.badge {
  float: right;
  margin-top: 8px;
  margin-left: 5px;
}
.sidebar .sidebar-content .sidebar-menu .sidebar-dropdown > a:after {
  font: var(--fa-font-solid);
  content: "\f105";
  display: inline-block;
  font-style: normal;
  font-variant: normal;
  text-rendering: auto;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-align: center;
  background: 0 0;
  position: absolute;
  right: 15px;
  top: 14px;
  transition: transform 0.3s ease;
}
.sidebar .sidebar-content .sidebar-menu .sidebar-dropdown .sidebar-submenu {
  overflow: hidden;
}
.sidebar .sidebar-content .sidebar-menu .sidebar-dropdown .sidebar-submenu ul {
  padding: 5px 0;
}
.sidebar .sidebar-content .sidebar-menu .sidebar-dropdown .sidebar-submenu li {
  font-size: 13px;
}
.sidebar .sidebar-content .sidebar-menu .sidebar-dropdown .sidebar-submenu li a .badge,
.sidebar .sidebar-content .sidebar-menu .sidebar-dropdown .sidebar-submenu li a .label {
  float: right;
  margin-top: 0;
}
.sidebar .sidebar-content .sidebar-menu .sidebar-dropdown .sidebar-submenu li a.active {
  font-weight: bold;
  color: #fff;
}
.sidebar .sidebar-content .sidebar-menu .sidebar-dropdown.active > a:after {
  transform: rotate(90deg);
  right: 15px;
}
.sidebar {
  background-color: #1d1d1d;
}
.sidebar .sidebar-profile,
.sidebar .sidebar-menu {
  border-top: 1px solid #2b2b2b;
}
.sidebar .sidebar-profile .user-info .db-user,
.sidebar .sidebar-profile .user-info .user-status,
.sidebar .sidebar-header > a,
.sidebar .sidebar-menu ul li a,
.sidebar #close-sidebar {
  color: #bdbdbd;
}
.sidebar .sidebar-menu ul li:hover > a,
.sidebar .sidebar-menu .sidebar-dropdown.active > a,
.sidebar .sidebar-profile .user-info,
.sidebar .sidebar-header > a:hover,
.sidebar #close-sidebar:hover {
  color: #ffffff;
}
.sidebar ul li:hover a i,
.sidebar .sidebar-dropdown .sidebar-submenu li a:hover:before,
.sidebar .sidebar-menu .sidebar-dropdown.active a i {
  color: #ffffff;
}
.sidebar .sidebar-menu ul li a i,
.sidebar .sidebar-menu .sidebar-dropdown div {
  background-color: #2b2b2b;
  border: none;
  margin-left: 1px;
}
.sidebar .sidebar-menu .header-menu span {
  color: #6c7b88;
}
.sidebar.sidebar-bg {
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}
.sidebar.sidebar-bg:before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  background-color: rgba(29, 29, 29, 0.85);
}
.sidebar.sidebar-bg .sidebar-profile,
.sidebar.sidebar-bg .sidebar-menu {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}
.sidebar.sidebar-bg .sidebar-menu ul li a i,
.sidebar.sidebar-bg .sidebar-menu .sidebar-dropdown div {
  background-color: rgba(255, 255, 255, 0.1);
}
.sidebar-button {
  position: fixed;
  bottom: 10px;
  left: 10px;
}
