import { APP_INITIALIZER, enableProdMode, importProvidersFrom, provideZonelessChangeDetection } from '@angular/core';

import { KEIRA_APP_CONFIG } from './environments/environment';
import { AppComponent } from './app/app.component';
import { TranslateHttpLoader } from '@ngx-translate/http-loader';
import { TranslateModule, TranslateLoader, TranslateService } from '@ngx-translate/core';
import { UiSwitchModule } from 'ngx-ui-switch';
import { ToastrModule } from 'ngx-toastr';
import { TooltipModule } from 'ngx-bootstrap/tooltip';
import { TabsModule } from 'ngx-bootstrap/tabs';
import { ModalModule } from 'ngx-bootstrap/modal';
import { BsDropdownModule } from 'ngx-bootstrap/dropdown';
import { withInterceptorsFromDi, provideHttpClient, HttpClient } from '@angular/common/http';
import { BrowserModule, bootstrapApplication } from '@angular/platform-browser';
import { HIGHLIGHT_OPTIONS } from 'ngx-highlightjs';
import { KEIRA_APP_CONFIG_TOKEN, highlightOptions, toastrConfig, uiSwitchConfig } from '@keira/shared/config';
import { provideRouter, withHashLocation } from '@angular/router';
import { KEIRA_ROUTES } from './app/routes';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';

if (KEIRA_APP_CONFIG.production) {
  enableProdMode();
}

export function createTranslateLoader(http: HttpClient) {
  const isFileProtocol = typeof window !== 'undefined' && window.location?.protocol === 'file:';
  // Electron 打包（file://）时 assets 在应用根目录；Web 部署时我们将静态文件放在 /keira/web 下
  const prefix = isFileProtocol ? './assets/i18n/' : './web/assets/i18n/';
  return new TranslateHttpLoader(http, prefix, '.json');
}

export function initTranslateFactory(translate: TranslateService) {
  return () => {
    const browserLang = translate.getBrowserLang();
    const supported = new Set(['en', 'zh', 'es', 'ru', 'fr', 'de', 'pt', 'sv']);

    const stored = typeof window !== 'undefined' ? window.localStorage.getItem('keira.lang') : null;
    const initial = stored && supported.has(stored) ? stored : browserLang && supported.has(browserLang) ? browserLang : 'en';

    translate.setDefaultLang(initial);
    translate.use(initial).subscribe();
  };
}

bootstrapApplication(AppComponent, {
  providers: [
    provideZonelessChangeDetection(),
    importProvidersFrom(
      /* Angular */
      BrowserModule,
      BrowserAnimationsModule,
      ReactiveFormsModule,
      FormsModule,
      /* External Libraries */
      BsDropdownModule.forRoot(),
      ModalModule.forRoot(),
      TabsModule.forRoot(),
      TooltipModule.forRoot(),
      ToastrModule.forRoot(toastrConfig),
      UiSwitchModule.forRoot(uiSwitchConfig),
      TranslateModule.forRoot({
        loader: {
          provide: TranslateLoader,
          useFactory: createTranslateLoader,
          deps: [HttpClient],
        },
        defaultLanguage: 'en',
      }),
    ),
    /* Config */
    provideRouter(KEIRA_ROUTES, withHashLocation()),
    { provide: KEIRA_APP_CONFIG_TOKEN, useValue: KEIRA_APP_CONFIG },
    {
      provide: HIGHLIGHT_OPTIONS,
      useValue: highlightOptions,
    },
    provideHttpClient(withInterceptorsFromDi()),
    {
      provide: APP_INITIALIZER,
      multi: true,
      useFactory: initTranslateFactory,
      deps: [TranslateService],
    },
  ],
}).catch((err) => console.error(err));
